CREATE TABLE IF NOT EXISTS customers (id BIGINT PRIMARY KEY, email VARCHAR(100) NOT NULL CONSTRAINT customers_email_key UNIQUE);
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY, customer_email VARCHAR(100) NOT NULL CONSTRAINT payments_customer_fkey REFERENCES customers (email));
CREATE TABLE IF NOT EXISTS invoices (id BIGINT PRIMARY KEY, customer_email VARCHAR(100) NOT NULL CONSTRAINT invoices_customer_fkey REFERENCES customers (email) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS readings (id BIGINT PRIMARY KEY, reading VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS tags (id BIGINT PRIMARY KEY, labels TEXT[] NOT NULL);
